SELECT  FROM workflow_run
WHERE workspace_id = #{workspaceId}
  AND workflow_id = #{workflowId}
  AND dedupe_key = #{dedupeKey}

SELECT  FROM workflow_run
WHERE workspace_id = #{workspaceId}
  AND workflow_id = #{workflowId}
  AND id = #{id}

SELECT  FROM workflow_run
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

SELECT  FROM workflow_run
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'running'
  AND lease_owner = #{leaseOwner}
  AND lease_until >= CURRENT_TIMESTAMP(6)
FOR UPDATE

SELECT  FROM workflow_run
WHERE workspace_id = #{workspaceId}
  AND workflow_id = #{workflowId}
  AND trigger_key = #{triggerKey}
  AND status = 'running'
ORDER BY id
LIMIT #{limit}

SELECT COALESCE(MAX(sequence_number) + 1, 0)
FROM workflow_step_run
WHERE workspace_id = #{workspaceId} AND workflow_run_id = #{workflowRunId}

SELECT  FROM workflow_step_run
WHERE workspace_id = #{workspaceId}
  AND workflow_run_id = #{workflowRunId}
  AND node_id = #{nodeId}
FOR UPDATE

mapper.update:
UPDATE workflow_step_attempt
SET status = 'succeeded', finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND workflow_run_id = #{workflowRunId}
  AND workflow_step_run_id = #{workflowStepRunId}
  AND attempt_number = #{attemptNumber}
  AND status = 'running'

UPDATE workflow_step_attempt
SET status = #{status}, error_code = #{errorCode}, finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND workflow_run_id = #{workflowRunId}
  AND workflow_step_run_id = #{workflowStepRunId}
  AND attempt_number = #{attemptNumber}
  AND status = 'running'

UPDATE workflow_step_attempt
SET status = 'abandoned', error_code = #{errorCode}, finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND workflow_run_id = #{workflowRunId}
  AND workflow_step_run_id = #{workflowStepRunId}
  AND status = 'running'

UPDATE workflow_step_run
SET status = 'succeeded',
    attempt_count = #{attemptCount},
    selected_outcome = #{selectedOutcome},
    selected_edge_id = #{selectedEdgeId},
    next_node_id = #{nextNodeId},
    failure_code = NULL,
    failure_message = NULL,
    finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND workflow_run_id = #{workflowRunId}
  AND node_id = #{nodeId}
  AND status = 'running'
  AND attempt_count = #{attemptCount}

UPDATE workflow_step_run
SET status = 'succeeded',
    selected_outcome = 'next',
    selected_edge_id = #{selectedEdgeId},
    next_node_id = #{nextNodeId},
    finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND workflow_run_id = #{workflowRunId}
  AND node_id = #{nodeId}
  AND node_type = 'delay'
  AND status = 'waiting'

UPDATE workflow_step_run
SET status = 'failed',
    selected_outcome = NULL,
    selected_edge_id = NULL,
    next_node_id = NULL,
    failure_code = #{failureCode},
    failure_message = #{failureMessage},
    finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND workflow_run_id = #{workflowRunId}
  AND node_id = #{nodeId}
  AND status IN ('running', 'waiting')

UPDATE workflow_step_run
SET status = 'cancelled',
    selected_outcome = NULL,
    selected_edge_id = NULL,
    next_node_id = NULL,
    failure_code = NULL,
    failure_message = NULL,
    finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND workflow_run_id = #{workflowRunId}
  AND node_id = #{nodeId}
  AND status IN ('running', 'waiting')

UPDATE workflow_run
SET status = 'queued', lease_owner = NULL, lease_until = NULL
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'running'
  AND lease_owner = #{leaseOwner}
  AND lease_until >= CURRENT_TIMESTAMP(6)
  AND wait_kind IS NULL
  AND resume_at IS NULL
  AND cancel_requested_at IS NULL

UPDATE workflow_run
SET wait_kind = NULL, resume_at = NULL
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'running'
  AND current_node_id = #{expectedNodeId}
  AND wait_kind = 'retry'
  AND resume_at IS NOT NULL
  AND lease_owner = #{leaseOwner}
  AND lease_until >= CURRENT_TIMESTAMP(6)
  AND cancel_requested_at IS NULL

UPDATE workflow_run
SET current_node_id = #{nextNodeId}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'running'
  AND current_node_id = #{expectedNodeId}

UPDATE workflow_run
SET current_node_id = #{nextNodeId},
    wait_kind = NULL,
    resume_at = NULL
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'running'
  AND current_node_id = #{expectedNodeId}
  AND lease_owner = #{leaseOwner}
  AND lease_until >= CURRENT_TIMESTAMP(6)
  AND cancel_requested_at IS NULL

UPDATE workflow_run
SET status = 'succeeded', current_node_id = NULL, finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'running'
  AND current_node_id = #{expectedNodeId}

UPDATE workflow_run
SET status = 'succeeded',
    current_node_id = NULL,
    wait_kind = NULL,
    resume_at = NULL,
    lease_owner = NULL,
    lease_until = NULL,
    finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'running'
  AND current_node_id = #{expectedNodeId}
  AND lease_owner = #{leaseOwner}
  AND lease_until >= CURRENT_TIMESTAMP(6)
  AND cancel_requested_at IS NULL

UPDATE workflow_run
SET status = #{status},
    failure_node_id = #{expectedNodeId},
    failure_code = #{failureCode},
    failure_message = #{failureMessage},
    finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status IN ('queued', 'running', 'waiting')
  AND current_node_id = #{expectedNodeId}

UPDATE workflow_run
SET status = #{status},
    wait_kind = NULL,
    resume_at = NULL,
    lease_owner = NULL,
    lease_until = NULL,
    failure_node_id = #{expectedNodeId},
    failure_code = #{failureCode},
    failure_message = #{failureMessage},
    finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'running'
  AND current_node_id = #{expectedNodeId}
  AND lease_owner = #{leaseOwner}
  AND lease_until >= CURRENT_TIMESTAMP(6)

UPDATE workflow_run
SET cancel_requested_at = COALESCE(cancel_requested_at, #{requestedAt})
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'running'

mapper.select:
SELECT EXISTS(
  SELECT 1
  FROM workflow_run
  WHERE workspace_id = #{workspaceId}
    AND workflow_id = #{workflowId}
  LIMIT 1
  FOR SHARE
)

SELECT CURRENT_TIMESTAMP(6)
FROM workflow
WHERE workspace_id = #{workspaceId} AND id = #{workflowId}

SELECT 
FROM workflow_run wr
JOIN workflow_version v
  ON v.workspace_id = wr.workspace_id
 AND v.workflow_id = wr.workflow_id
 AND v.id = wr.workflow_version_id
WHERE wr.workspace_id = #{workspaceId}
  AND wr.workflow_id = #{workflowId}
  AND wr.started_at <= #{asOf}

    AND (wr.started_at < #{beforeStartedAt}
      OR (wr.started_at = #{beforeStartedAt} AND wr.id < #{beforeId}))

ORDER BY wr.started_at DESC, wr.id DESC
LIMIT #{limit}

SELECT 
FROM workflow_run wr
JOIN workflow_version v
  ON v.workspace_id = wr.workspace_id
 AND v.workflow_id = wr.workflow_id
 AND v.id = wr.workflow_version_id
WHERE wr.workspace_id = #{workspaceId}
  AND wr.workflow_id = #{workflowId}
  AND wr.id = #{id}

SELECT  FROM workflow_step_run
WHERE workspace_id = #{workspaceId} AND workflow_run_id = #{workflowRunId}
ORDER BY sequence_number, id
